The meter is one component reused four times:

```tsx
function Meter({ label, value }: { label: string; value: number }) {
  return (
    <div className="meter">
      <span>{label}</span>
      <motion.i animate={{ width: `${value}%` }} transition={spring} />
      <b>{Math.round(value)}%</b>
    </div>
  );
}
```

The sampler reads the CPU from two `os.cpus()` snapshots a second apart:

```ts
export async function sample(): Promise<HardwareSample> {
  const before = os.cpus();
  await sleep(1000);
  const cpu = busyShare(before, os.cpus());
  const ram = 1 - os.freemem() / os.totalmem();
  const gpu = await readNvidiaSmi().catch(() => undefined);
  return { cpu, ram, gpu: gpu?.util, vram: gpu?.memory };
}
```
